}

function shadeOf(owner) { return owner === 'free' ? C_BK : (owner === 'L1' ? C_L1 : C_L2); }
function inkOf(owner) { return owner === 'free' ? '#ffffff' : '#111111'; }

/* ---------- cells ---------- */
function drawSlash(g, x, y, color) {
  g.line(x + 11, y + ROWH - 13, x + CW - 11, y + 13)
    .stroke({ color: color, width: 3, linecap: 'round' });
}

function drawKey(g, x, y, idx, color) {
  var t1 = g.text('k').font({ family: SERIF, size: 28, style: 'italic', anchor: 'middle' }).fill(color);
  t1.center(x + CW / 2 - 8, y + ROWH / 2 - 2);
  var t2 = g.text(String(idx)).font({ family: SERIF, size: 16, anchor: 'middle' }).fill(color);
  t2.center(x + CW / 2 + 10, y + ROWH / 2 + 9);
}

function tipText(i, row, v) {
  if (row === 'next') {
    if (v === 'nil') return 'next[' + i + '] = NIL — slot ' + i + ' is the last object of its list';
    return 'next[' + i + '] = ' + v + ' — an index, not data: the next object lives in slot ' + v;
  }
  if (row === 'prev') {
    if (v === 'none') return 'slot ' + i + ' is on the free list: a free slot needs no back pointer';
    if (v === 'nil') return 'prev[' + i + '] = NIL — slot ' + i + ' is the head of its list';
    return 'prev[' + i + '] = ' + v + ' — the previous object lives in slot ' + v;
  }
  if (v === 'none') return 'slot ' + i + ' is free: no key is stored here';
  return 'key[' + i + '] = k' + i + ' — the payload held by object ' + i;
}

function popText(i, row, v, owner) {
  var own = owner === 'free' ? 'the free list' : 'list ' + owner;
  if (row === 'key') {
    return ['key[' + i + ']',
      v === 'none'
        ? 'Slot ' + i + ' belongs to the free list, so its key and prev entries are meaningless (shown struck out). Allocation will overwrite them; nothing is ever copied elsewhere.'
        : 'Slot ' + i + ' currently belongs to ' + own + '. The object IS the index ' + i + ': its data sits in key[' + i + '] and its links in next[' + i + '] and prev[' + i + '].'];
  }
  if (v === 'nil') return [row + '[' + i + '] = NIL', 'A NIL link (the diagonal slash) terminates a chain. Following next pointers from a head until NIL enumerates exactly one of the three structures sharing this table.'];
  if (v === 'none') return ['slot ' + i + ' is free', 'Free slots store only a next pointer — enough to keep them threaded on the free chain. No record has to be moved to free or reuse a slot.'];
  return [row + '[' + i + '] = ' + v, 'This number is an index into the same three arrays, not a value. Slot ' + i + ' belongs to ' + own + ', and so does slot ' + v + ' — shading (ownership) is defined entirely by which chain reaches a slot.'];
}

function renderCells() {
  cellLayer.clear();
  for (var i = 1; i <= 10; i++) {
    (function (i) {
      var s = model.slots[i];
      var fill = shadeOf(s.owner), ink = inkOf(s.owner);
      ROWS.forEach(function (row) {
        var x = colX(i), y = ROWY[row], v = s[row];
        var g = cellLayer.group();
