            var d = Math.abs(cx(v) - cx(i));
            var h = 34 + Math.min(62, d * 0.2);
            arcArrow(hoverLayer, cx(i), yy, cx(v), yy, (row === 'prev') ? -h : h, HOV);
          } else if (v === 'nil') {
