/* ---------- highlight helpers ---------- */
function hlCol(layer, i, color, op) {
  var x = colX(i) - 4, y = ROWY.next - 4;
  var h = 3 * ROWH + 2 * RG + 8;
  layer.rect(CW + 8, h).move(x, y).fill(color).opacity(op == null ? 0.16 : op);
  var r = layer.rect(CW + 8, h).move(x, y).fill('none')
    .stroke({ color: color, width: 4 }).radius(4);
  r.opacity(0);
  r.animate(180).opacity(1);
  return r;
}
function hlCell(layer, i, row, color) {
  layer.rect(CW + 6, ROWH + 6).move(colX(i) - 3, ROWY[row] - 3).fill('none')
    .stroke({ color: color, width: 4 }).radius(3);
}
function arcArrow(layer, x1, y1, x2, y2, h, color) {
  var c1y = y1 - h, c2y = y2 - h;
  var d = 'M' + x1 + ' ' + y1 + ' C' + x1 + ' ' + c1y + ' ' + x2 + ' ' + c2y + ' ' + x2 + ' ' + y2;
  var p = layer.path(d).fill('none').stroke({ color: color, width: 3.2, linecap: 'round' });
  p.opacity(0); p.animate(200).opacity(1);
  var dir = h > 0 ? 1 : -1;
  var head = layer.polygon([[x2 - 8, y2 - 12 * dir], [x2 + 8, y2 - 12 * dir], [x2, y2]].map(function (q) { return q.join(','); }).join(' '))
    .fill(color);
  head.opacity(0); head.animate(200).opacity(1);
}

