var traceToken = 0, traceTimers = [];
function clearTrace() {
  traceToken++;
  traceTimers.forEach(clearTimeout); traceTimers = [];
  traceLayer.clear();
  state.trace = null;
  updateButtons();
}
function traceList(name) {
  clearTrace();
  state.trace = name;
  updateButtons();
