    st: { allocFree: 'initial', targetList: 'L1' }, trace: 'L2'
  },
  {
    title: 'The free list needs only one link',
    narration: 'The free head (10) gives 10 → 4 → 8 → NIL. The key and prev rows of these slots are struck out with dotted rules — a free slot carries no data and needs no back pointer.',
    st: { allocFree: 'initial', targetList: 'L1' }, trace: 'free'
  },
  {
    title: 'Allocate a slot',
    narration: 'Allocate: slot 10 is popped off the free chain, free is reset to 4, and slot 10 is spliced onto the front of L1 — only next[10], key[10], prev[10], prev[3] and the two head pointers change (dashed outlines).',
    st: { allocFree: 'allocated', targetList: 'L1' }, trace: 'L1'
  },
  {
    title: 'Free it again',
    narration: 'Free: slot 10 is unlinked from L1, its key and prev are struck out again, next[10] is set to the old free head 4, and free points back at 10. No record ever moved in memory.',
    st: { allocFree: 'returned', targetList: 'L1' }, trace: 'free'
  }
];
var curStep = 0;
function applyStep() {
  var s = steps[curStep];
  applyState(s.st.allocFree, s.st.targetList);
  var t = document.getElementById('stepTitle');
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  if (t) t.textContent = (curStep + 1) + '. ' + s.title;
  if (n) n.textContent = s.narration;
  if (l) l.textContent = (curStep + 1) + ' / ' + steps.length;
  if (s.trace) setTimeout(function () { traceList(s.trace); }, 220);
}
function nextStep() { curStep = (curStep + 1) % steps.length; applyStep(); }
function prevStep() { curStep = (curStep - 1 + steps.length) % steps.length; applyStep(); }

/* ---------- init ---------- */
model = buildModel();
renderCells();
renderHeads();
applyStep();
window.__markRendered();
// @FIGURE_CODE_END

