// @FIGURE_CODE_BEGIN
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var ACC = '#ED8B00', HOV = '#1E88E5';
var C_L1 = '#EAEAEA', C_L2 = '#9C9C9C', C_BK = '#000000';

/* ---------- tight canvas: viewBox hugs the actual content ---------- */
var W = 1140, H = 358;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);
draw.rect(W, H).fill('#ffffff');

var PANX = 340, PANY = 92, PAD = 12, CW = 64, CG = 13, ROWH = 66, RG = 4;
var PANW = PAD * 2 + 10 * CW + 9 * CG;      // 781
var PANH = PAD * 2 + 3 * ROWH + 2 * RG;     // 230
var ROWS = ['next', 'key', 'prev'];
var ROWY = { next: PANY + PAD, key: PANY + PAD + ROWH + RG, prev: PANY + PAD + 2 * (ROWH + RG) };
var PANB = PANY + PANH;

function colX(i) { return PANX + PAD + (i - 1) * (CW + CG); }
function cx(i) { return colX(i) + CW / 2; }

var panelLayer = draw.group();
var cellLayer = draw.group();
var strikeLayer = draw.group().attr('pointer-events', 'none');
var traceLayer = draw.group().attr('pointer-events', 'none');
var hoverLayer = draw.group().attr('pointer-events', 'none');
var labelLayer = draw.group().attr('pointer-events', 'none');
var headLayer = draw.group();

/* ---------- static panel, column indices, row labels ---------- */
panelLayer.rect(PANW, PANH).move(PANX, PANY).fill('#000');

function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}
for (var i = 1; i <= 10; i++) {
  halo(labelLayer.text(String(i))
    .font({ family: SERIF, size: 30, anchor: 'middle' })
    .fill('#000')).center(cx(i), 60);
}
ROWS.forEach(function (r) {
  var t = labelLayer.text(r)
    .font({ family: SERIF, size: 30, style: 'italic', anchor: 'middle' })
    .fill('#000');
  t.center(PANX - 44, ROWY[r] + ROWH / 2);
});

/* ---------- model ---------- */
var state = { allocFree: 'initial', target: 'L1', trace: null };
var model = null;

function buildModel() {
  var def = {
    1: [5, 1, 7, 'L2'], 2: ['nil', 2, 6, 'L1'], 3: [6, 3, 'nil', 'L1'],
    4: [8, 'none', 'none', 'free'], 5: ['nil', 5, 1, 'L2'], 6: [2, 6, 3, 'L1'],
    7: [1, 7, 9, 'L2'], 8: ['nil', 'none', 'none', 'free'], 9: [7, 9, 'nil', 'L2'],
    10: [4, 'none', 'none', 'free']
  };
  var s = {};
  for (var i = 1; i <= 10; i++) {
    s[i] = { next: def[i][0], key: def[i][1], prev: def[i][2], owner: def[i][3] };
  }
  var m = { slots: s, heads: { free: 10, L1: 3, L2: 9 }, changed: {} };
  if (state.allocFree === 'allocated') {
    var T = state.target, old = m.heads[T];
    m.heads.free = 4;
    s[10].owner = T; s[10].key = 10; s[10].next = old; s[10].prev = 'nil';
    s[old].prev = 10;
    m.heads[T] = 10;
    m.changed['next10'] = 1; m.changed['key10'] = 1; m.changed['prev10'] = 1;
    m.changed['prev' + old] = 1; m.changed['headfree'] = 1; m.changed['head' + T] = 1;
  } else if (state.allocFree === 'returned') {
    var back = (state.target === 'L1') ? 3 : 9;
    m.changed['next10'] = 1; m.changed['key10'] = 1; m.changed['prev10'] = 1;
    m.changed['prev' + back] = 1; m.changed['headfree'] = 1; m.changed['head' + state.target] = 1;
  }
  return m;
}

function shadeOf(owner) { return owner === 'free' ? C_BK : (owner === 'L1' ? C_L1 : C_L2); }
function inkOf(owner) { return owner === 'free' ? '#ffffff' : '#111111'; }

/* ---------- cell glyphs ---------- */
function drawSlash(g, x, y, color) {
  g.line(x + 12, y + ROWH - 14, x + CW - 12, y + 14)
    .stroke({ color: color, width: 3.2, linecap: 'round' });
}

function drawKey(g, x, y, idx, color) {
  var t1 = g.text('k').font({ family: SERIF, size: 32, style: 'italic', anchor: 'middle' }).fill(color);
  t1.center(x + CW / 2 - 9, y + ROWH / 2 - 3);
  var t2 = g.text(String(idx)).font({ family: SERIF, size: 19, anchor: 'middle' }).fill(color);
  t2.center(x + CW / 2 + 11, y + ROWH / 2 + 11);
}

function tipText(i, row, v) {
  if (row === 'next') {
    if (v === 'nil') return 'next[' + i + '] = NIL — slot ' + i + ' is the last object of its list';
    return 'next[' + i + '] = ' + v + ' — an index, not data: the next object lives in slot ' + v;
  }
  if (row === 'prev') {
    if (v === 'none') return 'slot ' + i + ' is on the free list: a free slot needs no back pointer';
    if (v === 'nil') return 'prev[' + i + '] = NIL — slot ' + i + ' is the head of its list';
    return 'prev[' + i + '] = ' + v + ' — the previous object lives in slot ' + v;
  }
  if (v === 'none') return 'slot ' + i + ' is free: no key is stored here';
  return 'key[' + i + '] = k' + i + ' — the payload held by object ' + i;
}

function popText(i, row, v, owner) {
  var own = owner === 'free' ? 'the free list' : 'list ' + owner;
  if (row === 'key') {
    return ['key[' + i + ']',
      v === 'none'
        ? 'Slot ' + i + ' belongs to the free list, so its key and prev entries are meaningless (struck out with dotted rules). Allocation simply overwrites them; nothing is ever copied elsewhere.'
        : 'Slot ' + i + ' currently belongs to ' + own + '. The object IS the index ' + i + ': its data sits in key[' + i + '] and its links in next[' + i + '] and prev[' + i + '].'];
  }
  if (v === 'nil') return [row + '[' + i + '] = NIL', 'A NIL link (the diagonal slash) terminates a chain. Following next pointers from a head until NIL enumerates exactly one of the three structures sharing this table.'];
  if (v === 'none') return ['slot ' + i + ' is free', 'Free slots store only a next pointer — enough to keep them threaded on the free chain. No record has to be moved to free or reuse a slot.'];
  return [row + '[' + i + '] = ' + v, 'This number is an index into the same three arrays, not a value. Slot ' + i + ' belongs to ' + own + ', and so does slot ' + v + ' — shading (ownership) is defined entirely by which chain reaches a slot.'];
}

/* ---------- cells ---------- */
function renderCells() {
  cellLayer.clear();
  strikeLayer.clear();
  for (var i = 1; i <= 10; i++) {
    (function (i) {
      var s = model.slots[i];
      var fill = shadeOf(s.owner), ink = inkOf(s.owner);
      ROWS.forEach(function (row) {
        var x = colX(i), y = ROWY[row], v = s[row];
        var g = cellLayer.group();
        if (v === 'none') {
          g.rect(CW, ROWH).move(x, y).fill('#000');
        } else {
          g.rect(CW, ROWH).move(x, y).fill(fill);
          if (v === 'nil') {
            drawSlash(g, x, y, ink);
          } else if (row === 'key') {
            drawKey(g, x, y, v, ink);
          } else {
            var t = g.text(String(v)).font({
              family: SERIF, size: 33, anchor: 'middle',
              weight: s.owner === 'free' ? 'bold' : 'normal'
            }).fill(ink);
            t.center(x + CW / 2, y + ROWH / 2);
          }
        }
        if (model.changed[row + i]) {
          g.rect(CW + 6, ROWH + 6).move(x - 3, y - 3).fill('none')
            .stroke({ color: ACC, width: 3, dasharray: '6,4' }).radius(3);
        }
        var hit = g.rect(CW, ROWH).move(x, y).fill('#fff').opacity(0).css('cursor', 'pointer');
        hit.on('mousemove', function (e) { showTooltip(tipText(i, row, v), e); });
        hit.on('mouseenter', function () {
          hoverLayer.clear();
          if (typeof v === 'number' && row !== 'key') {
            hlCol(hoverLayer, v, HOV, 0.14);
            var d = Math.abs(cx(v) - cx(i));
            if (row === 'prev') {
              arcArrow(hoverLayer, cx(i), PANB, cx(v), PANB, -(22 + Math.min(20, d * 0.1)), HOV);
            } else {
              arcArrow(hoverLayer, cx(i), PANY, cx(v), PANY, 28 + Math.min(46, d * 0.16), HOV);
            }
          } else if (v === 'nil') {
            hlCell(hoverLayer, i, row, HOV);
          }
        });
        hit.on('mouseleave', function () { hideTooltip(); hoverLayer.clear(); });
        hit.on('click', function () {
          var p = popText(i, row, v, s.owner);
          showPopup(p[0], p[1]);
        });
      });

      /* thick white dotted strike rules across unused key / prev cells */
      if (s.key === 'none' && s.prev === 'none') {
        var xs = colX(i);
        [ROWY.key - RG / 2, ROWY.prev - RG / 2].forEach(function (yy) {
          strikeLayer.line(xs + 1, yy, xs + CW - 1, yy)
            .stroke({ color: '#ffffff', width: 7, dasharray: '8,8', linecap: 'butt' });
        });
      }
    })(i);
  }
}

/* ---------- head boxes ---------- */
var HEADS = [
  { name: 'free', label: 'free', y: 26, fill: C_BK, ink: '#fff' },
  { name: 'L2', label: 'L', sub: '2', y: 178, fill: C_L2, ink: '#111' },
  { name: 'L1', label: 'L', sub: '1', y: 248, fill: C_L1, ink: '#111' }
];
var BX = 100, BS = 58;

function renderHeads() {
  headLayer.clear();
  HEADS.forEach(function (h) {
    var g = headLayer.group().css('cursor', 'pointer');
    var cy = h.y + BS / 2;
    if (h.sub) {
      var lt = g.text(h.label).font({ family: SERIF, size: 31, style: 'italic', anchor: 'middle' }).fill('#000');
      lt.center(BX - 46, cy - 3);
      var st = g.text(h.sub).font({ family: SERIF, size: 19, anchor: 'middle' }).fill('#000');
      st.center(BX - 30, cy + 11);
    } else {
      var ft = g.text(h.label).font({ family: SERIF, size: 31, style: 'italic', anchor: 'middle' }).fill('#000');
      ft.center(BX - 40, cy - 2);
    }
    var r = g.rect(BS, BS).move(BX, h.y).fill(h.fill);
    if (h.name !== 'free') r.stroke({ color: '#333', width: 1.5 });
    var vt = g.text(String(model.heads[h.name]))
      .font({ family: SERIF, size: 31, anchor: 'middle', weight: h.name === 'free' ? 'bold' : 'normal' })
      .fill(h.ink);
    vt.center(BX + BS / 2, cy);
    if (model.changed['head' + h.name]) {
      g.rect(BS + 8, BS + 8).move(BX - 4, h.y - 4).fill('none')
        .stroke({ color: ACC, width: 3, dasharray: '6,4' }).radius(3);
    }
    g.on('mousemove', function (e) {
      showTooltip(h.name + ' head = ' + model.heads[h.name] + ' — click to trace this chain', e);
    });
    g.on('mouseleave', hideTooltip);
    g.on('click', function () { traceList(h.name); });
  });
}

function headBoxRect(name) {
  for (var k = 0; k < HEADS.length; k++) if (HEADS[k].name === name) return { x: BX, y: HEADS[k].y };
  return null;
}

/* ---------- highlight helpers ---------- */
function hlCol(layer, i, color, op) {
  var x = colX(i) - 4, y = ROWY.next - 4;
  var h = 3 * ROWH + 2 * RG + 8;
  layer.rect(CW + 8, h).move(x, y).fill(color).opacity(op == null ? 0.16 : op);
  var r = layer.rect(CW + 8, h).move(x, y).fill('none')
    .stroke({ color: color, width: 4 }).radius(4);
  r.opacity(0);
  r.animate(180).opacity(1);
  return r;
}
function hlCell(layer, i, row, color) {
  layer.rect(CW + 6, ROWH + 6).move(colX(i) - 3, ROWY[row] - 3).fill('none')
    .stroke({ color: color, width: 4 }).radius(3);
}
function arcArrow(layer, x1, y1, x2, y2, h, color) {
  var d = 'M' + x1 + ' ' + y1 + ' C' + x1 + ' ' + (y1 - h) + ' ' + x2 + ' ' + (y2 - h) + ' ' + x2 + ' ' + y2;
  var p = layer.path(d).fill('none').stroke({ color: color, width: 3.2, linecap: 'round' });
