// @FIGURE_CODE_BEGIN
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var ACC = '#ED8B00', HOV = '#1E88E5';
var C_L1 = '#EAEAEA', C_L2 = '#9C9C9C', C_BK = '#000000';

/* reclaim a little canvas padding so the table fills the frame width */
try { document.getElementById('container').style.setProperty('--figure-canvas-padding', '8px'); } catch (e) { }

/* ---------- tight viewBox: content occupies ~76% of the width ---------- */
var W = 1077, H = 410;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);
draw.rect(W, H).fill('#ffffff');

var PANX = 250, PANY = 108, PAD = 10, CW = 68, CG = 13, ROWH = 76, RG = 5;
var PANW = PAD * 2 + 10 * CW + 9 * CG;      /* 817 */
var PANH = PAD * 2 + 3 * ROWH + 2 * RG;     /* 258 */
var ROWS = ['next', 'key', 'prev'];
var ROWY = { next: PANY + PAD, key: PANY + PAD + ROWH + RG, prev: PANY + PAD + 2 * (ROWH + RG) };
var PANB = PANY + PANH;
var IDXY = 52;                              /* centre of the index header row */

function colX(i) { return PANX + PAD + (i - 1) * (CW + CG); }
function cx(i) { return colX(i) + CW / 2; }

var panelLayer = draw.group();
var cellLayer = draw.group();
var strikeLayer = draw.group().attr('pointer-events', 'none');
var traceLayer = draw.group().attr('pointer-events', 'none');
var hoverLayer = draw.group().attr('pointer-events', 'none');
var labelLayer = draw.group().attr('pointer-events', 'none');
var headLayer = draw.group();

/* ---------- text helpers ---------- */
function mkText(layer, str, size, o) {
  o = o || {};
  return layer.text(str).font({
    family: SERIF, size: size, anchor: 'middle',
    style: o.italic ? 'italic' : 'normal',
    weight: o.bold ? 'bold' : 'normal'
  }).fill(o.fill || '#000');
}

/* base glyph + true subscript on a shared baseline (single <text>, tspan dy) */
function mkSub(layer, base, sub, size, o) {
  o = o || {};
  var subSize = Math.round(size * 0.60);
  var dy = Math.round(size * 0.22);
  var t = layer.text(function (add) {
    add.tspan(base).font({ style: o.baseItalic === false ? 'normal' : 'italic' });
    add.tspan(sub).font({ size: subSize, style: 'normal' }).dy(dy);
  }).font({ family: SERIF, size: size, anchor: 'start' }).fill(o.fill || '#000');
  return t;
}

function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}
function rightAlign(t, xRight, cy) {
  var b = t.bbox();
  t.center(xRight - b.width / 2, cy);
  return t;
}

/* ---------- static panel, column indices, row labels ---------- */
panelLayer.rect(PANW, PANH).move(PANX, PANY).fill('#000');

for (var i = 1; i <= 10; i++) {
  halo(mkText(labelLayer, String(i), 34)).center(cx(i), IDXY);
}
ROWS.forEach(function (r) {
  var t = mkText(labelLayer, r, 34, { italic: true });
  rightAlign(t, PANX - 16, ROWY[r] + ROWH / 2);
});

/* ---------- model ---------- */
var state = { allocFree: 'initial', target: 'L1', trace: null };
var model = null;

function buildModel() {
  var def = {
    1: [5, 1, 7, 'L2'], 2: ['nil', 2, 6, 'L1'], 3: [6, 3, 'nil', 'L1'],
    4: [8, 'none', 'none', 'free'], 5: ['nil', 5, 1, 'L2'], 6: [2, 6, 3, 'L1'],
    7: [1, 7, 9, 'L2'], 8: ['nil', 'none', 'none', 'free'], 9: [7, 9, 'nil', 'L2'],
    10: [4, 'none', 'none', 'free']
  };
  var s = {};
  for (var i = 1; i <= 10; i++) {
    s[i] = { next: def[i][0], key: def[i][1], prev: def[i][2], owner: def[i][3] };
  }
  var m = { slots: s, heads: { free: 10, L1: 3, L2: 9 }, changed: {} };
  if (state.allocFree === 'allocated') {
    var T = state.target, old = m.heads[T];
    m.heads.free = 4;
    s[10].owner = T; s[10].key = 10; s[10].next = old; s[10].prev = 'nil';
    s[old].prev = 10;
    m.heads[T] = 10;
    m.changed['next10'] = 1; m.changed['key10'] = 1; m.changed['prev10'] = 1;
    m.changed['prev' + old] = 1; m.changed['headfree'] = 1; m.changed['head' + T] = 1;
  } else if (state.allocFree === 'returned') {
    var back = (state.target === 'L1') ? 3 : 9;
    m.changed['next10'] = 1; m.changed['key10'] = 1; m.changed['prev10'] = 1;
    m.changed['prev' + back] = 1; m.changed['headfree'] = 1; m.changed['head' + state.target] = 1;
  }
  return m;
}

function shadeOf(owner) { return owner === 'free' ? C_BK : (owner === 'L1' ? C_L1 : C_L2); }
function inkOf(owner) { return owner === 'free' ? '#ffffff' : '#111111'; }

/* ---------- cell glyphs ---------- */
/* NIL slashes vary in slope and weight, as in the printed figure */
var SLASH_VARIANT = {
  next2: { pad: 12, top: 14, w: 3.4 },
  next5: { pad: 10, top: 11, w: 3.2 },
  next8: { pad: 13, top: 15, w: 4.2 },
  prev3: { pad: 7, top: 9, w: 2.8 },
  prev9: { pad: 11, top: 13, w: 3.4 }
};
function drawSlash(g, x, y, color, key) {
  var v = SLASH_VARIANT[key] || { pad: 11, top: 13, w: 3.4 };
  g.line(x + v.pad, y + ROWH - v.top, x + CW - v.pad, y + v.top)
    .stroke({ color: color, width: v.w, linecap: 'round' });
}

function drawKey(g, x, y, idx, color) {
  var t = mkSub(g, 'k', String(idx), 40, { fill: color });
  t.center(x + CW / 2, y + ROWH / 2 - 3);
}

function tipText(i, row, v) {
  if (row === 'next') {
    if (v === 'nil') return 'next[' + i + '] = NIL — slot ' + i + ' is the last object of its list';
    return 'next[' + i + '] = ' + v + ' — an index, not data: the next object lives in slot ' + v;
  }
  if (row === 'prev') {
    if (v === 'none') return 'slot ' + i + ' is on the free list: a free slot needs no back pointer';
    if (v === 'nil') return 'prev[' + i + '] = NIL — slot ' + i + ' is the head of its list';
    return 'prev[' + i + '] = ' + v + ' — the previous object lives in slot ' + v;
  }
  if (v === 'none') return 'slot ' + i + ' is free: no key is stored here';
  return 'key[' + i + '] = k' + i + ' — the payload held by object ' + i;
}

function popText(i, row, v, owner) {
  var own = owner === 'free' ? 'the free list' : 'list ' + owner;
  if (row === 'key') {
    return ['key[' + i + ']',
      v === 'none'
        ? 'Slot ' + i + ' belongs to the free list, so its key and prev entries are meaningless (struck out with dotted rules). Allocation simply overwrites them; nothing is ever copied elsewhere.'
        : 'Slot ' + i + ' currently belongs to ' + own + '. The object IS the index ' + i + ': its data sits in key[' + i + '] and its links in next[' + i + '] and prev[' + i + '].'];
  }
  if (v === 'nil') return [row + '[' + i + '] = NIL', 'A NIL link (the diagonal slash) terminates a chain. Following next pointers from a head until NIL enumerates exactly one of the three structures sharing this table.'];
  if (v === 'none') return ['slot ' + i + ' is free', 'Free slots store only a next pointer — enough to keep them threaded on the free chain. No record has to be moved to free or reuse a slot.'];
  return [row + '[' + i + '] = ' + v, 'This number is an index into the same three arrays, not a value. Slot ' + i + ' belongs to ' + own + ', and so does slot ' + v + ' — shading (ownership) is defined entirely by which chain reaches a slot.'];
}

/* ---------- cells ---------- */
function renderCells() {
  cellLayer.clear();
  strikeLayer.clear();
  for (var i = 1; i <= 10; i++) {
    (function (i) {
      var s = model.slots[i];
      var fill = shadeOf(s.owner), ink = inkOf(s.owner);
      ROWS.forEach(function (row) {
        var x = colX(i), y = ROWY[row], v = s[row];
        var g = cellLayer.group();
        if (v === 'none') {
          g.rect(CW, ROWH).move(x, y).fill('#000');
        } else {
          g.rect(CW, ROWH).move(x, y).fill(fill);
          if (v === 'nil') {
            drawSlash(g, x, y, ink, row + i);
          } else if (row === 'key') {
            drawKey(g, x, y, v, ink);
          } else {
            mkText(g, String(v), 40, { fill: ink, bold: s.owner === 'free' })
              .center(x + CW / 2, y + ROWH / 2);
          }
        }
        if (model.changed[row + i]) {
          g.rect(CW + 6, ROWH + 6).move(x - 3, y - 3).fill('none')
            .stroke({ color: ACC, width: 3.4, dasharray: '7,5' }).radius(3);
        }
        var hit = g.rect(CW, ROWH).move(x, y).fill('#fff').opacity(0).css('cursor', 'pointer');
        hit.on('mousemove', function (e) { showTooltip(tipText(i, row, v), e); });
        hit.on('mouseenter', function () {
          hoverLayer.clear();
          if (typeof v === 'number' && row !== 'key') {
            hlCol(hoverLayer, v, HOV, 0.14);
            var d = Math.abs(cx(v) - cx(i));
            if (row === 'prev') {
              arcArrow(hoverLayer, cx(i), PANB, cx(v), PANB, -(20 + Math.min(22, d * 0.075)), HOV);
            } else {
              arcArrow(hoverLayer, cx(i), PANY, cx(v), PANY, 22 + Math.min(24, d * 0.08), HOV);
            }
          } else if (v === 'nil') {
            hlCell(hoverLayer, i, row, HOV);
          }
        });
        hit.on('mouseleave', function () { hideTooltip(); hoverLayer.clear(); });
        hit.on('click', function () {
          var p = popText(i, row, v, s.owner);
          showPopup(p[0], p[1]);
        });
      });

      /* heavy white dotted strike rules spanning the FULL cell width */
      if (s.key === 'none' && s.prev === 'none') {
        var xs = colX(i);
        [ROWY.key - RG / 2, ROWY.prev - RG / 2].forEach(function (yy) {
          strikeLayer.line(xs, yy, xs + CW, yy)
            .stroke({ color: '#ffffff', width: 7, dasharray: '8,7', linecap: 'butt' });
        });
      }
    })(i);
  }
}

/* ---------- head boxes (aligned to the row band they point at) ---------- */
var BS = 76, BX = 84;
var HEADS = [
  { name: 'free', label: 'free', cy: IDXY, fill: C_BK, ink: '#fff' },
  { name: 'L2', label: 'L', sub: '2', cy: ROWY.key + ROWH / 2, fill: C_L2, ink: '#111' },
  { name: 'L1', label: 'L', sub: '1', cy: ROWY.prev + ROWH / 2, fill: C_L1, ink: '#111' }
];

function renderHeads() {
  headLayer.clear();
  HEADS.forEach(function (h) {
    var g = headLayer.group().css('cursor', 'pointer');
    var y = h.cy - BS / 2;
    var lt = h.sub ? mkSub(g, h.label, h.sub, 36, {}) : mkText(g, h.label, 36, { italic: true });
    rightAlign(lt, BX - 16, h.cy - (h.sub ? 3 : 0));
    var r = g.rect(BS, BS).move(BX, y).fill(h.fill);
    if (h.name !== 'free') r.stroke({ color: '#444', width: 1.6 });
    mkText(g, String(model.heads[h.name]), 38, { fill: h.ink, bold: h.name === 'free' })
      .center(BX + BS / 2, h.cy);
    if (model.changed['head' + h.name]) {
      g.rect(BS + 10, BS + 10).move(BX - 5, y - 5).fill('none')
        .stroke({ color: ACC, width: 3.4, dasharray: '7,5' }).radius(3);
    }
    g.on('mousemove', function (e) {
      showTooltip(h.name + ' head = ' + model.heads[h.name] + ' — click to trace this chain', e);
    });
    g.on('mouseleave', hideTooltip);
    g.on('click', function () { traceList(h.name); });
  });
}

function headBoxRect(name) {
  for (var k = 0; k < HEADS.length; k++) {
    if (HEADS[k].name === name) return { x: BX, y: HEADS[k].cy - BS / 2 };
  }
  return null;
}

/* ---------- highlight helpers ---------- */
function hlCol(layer, i, color, op) {
  var x = colX(i) - 4, y = ROWY.next - 4;
  var h = 3 * ROWH + 2 * RG + 8;
  layer.rect(CW + 8, h).move(x, y).fill(color).opacity(op == null ? 0.16 : op);
  var r = layer.rect(CW + 8, h).move(x, y).fill('none')
    .stroke({ color: color, width: 4.5 }).radius(4);
  r.opacity(0);
  r.animate(180).opacity(1);
  return r;
}
function hlCell(layer, i, row, color) {
  layer.rect(CW + 6, ROWH + 6).move(colX(i) - 3, ROWY[row] - 3).fill('none')
    .stroke({ color: color, width: 4.5 }).radius(3);
}
function arcArrow(layer, x1, y1, x2, y2, h, color) {
  var d = 'M' + x1 + ' ' + y1 + ' C' + x1 + ' ' + (y1 - h) + ' ' + x2 + ' ' + (y2 - h) + ' ' + x2 + ' ' + y2;
  var p = layer.path(d).fill('none').stroke({ color: color, width: 3.4, linecap: 'round' });
  p.opacity(0); p.animate(200).opacity(1);
  var dir = h > 0 ? 1 : -1;
  var head = layer.polygon([[x2 - 9, y2 - 14 * dir], [x2 + 9, y2 - 14 * dir], [x2, y2]]
    .map(function (q) { return q.join(','); }).join(' ')).fill(color);
  head.opacity(0); head.animate(200).opacity(1);
}

/* ---------- trace ---------- */
var traceToken = 0, traceTimers = [];
function clearTrace() {
  traceToken++;
  traceTimers.forEach(clearTimeout); traceTimers = [];
  traceLayer.clear();
  state.trace = null;
  updateButtons();
}
function traceList(name) {
  clearTrace();
  state.trace = name;
  updateButtons();
  var chain = [], cur = model.heads[name], guard = 0;
  while (typeof cur === 'number' && guard++ < 12) {
    chain.push(cur);
    var nx = model.slots[cur].next;
    cur = (nx === 'nil') ? null : nx;
  }
  var hb = headBoxRect(name);
  traceLayer.rect(BS + 12, BS + 12).move(hb.x - 6, hb.y - 6).fill('none')
    .stroke({ color: ACC, width: 4.5 }).radius(4);
  var tok = traceToken;
  chain.forEach(function (idx, k) {
    traceTimers.push(setTimeout(function () {
      if (tok !== traceToken) return;
      hlCol(traceLayer, idx, ACC, 0.18);
      if (k > 0) {
        var a = chain[k - 1], b = idx;
        var d = Math.abs(cx(b) - cx(a));
        arcArrow(traceLayer, cx(a), PANY, cx(b), PANY, 22 + Math.min(24, d * 0.08), ACC);
      }
    }, k * 430));
  });
  traceTimers.push(setTimeout(function () {
    if (tok !== traceToken) return;
    hlCell(traceLayer, chain[chain.length - 1], 'next', ACC);
  }, chain.length * 430));
}

/* ---------- state controls ---------- */
function applyState(af, target) {
  state.allocFree = af;
  state.target = target;
  var inp = document.getElementById('allocFreeInput');
  if (inp) inp.value = af;
  var sel = document.getElementById('targetListInput');
  if (sel) sel.value = target;
  model = buildModel();
  clearTrace();
  hoverLayer.clear();
  renderCells();
  renderHeads();
  updateButtons();
}
function set_allocFree(v) {
  applyState(v, state.target);
  if (v === 'allocated') setTimeout(function () { traceList(state.target); }, 260);
  else if (v === 'returned') setTimeout(function () { traceList('free'); }, 260);
}
function toggle_targetList(v) {
  applyState(state.allocFree, v);
  if (state.allocFree === 'allocated') setTimeout(function () { traceList(v); }, 260);
}
function updateButtons() {
  var map = { initial: 'resetBtn', allocated: 'allocBtn', returned: 'freeBtn' };
  ['resetBtn', 'allocBtn', 'freeBtn'].forEach(function (id) {
    var b = document.getElementById(id);
    if (b) b.classList.toggle('active', map[state.allocFree] === id);
  });
  [['L1', 'traceL1Btn'], ['L2', 'traceL2Btn'], ['free', 'traceFreeBtn']].forEach(function (p) {
    var b = document.getElementById(p[1]);
    if (b) b.classList.toggle('active', state.trace === p[0]);
  });
}

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'One table, three structures',
    narration: 'The black panel is a single set of parallel arrays indexed 1 to 10. Shading is the only thing distinguishing three separate structures living inside it: light gray for L1, medium gray for L2, and black for the free list.',
    st: { allocFree: 'initial', targetList: 'L1' }, trace: null
  },
  {
    title: 'Trace L1',
    narration: 'The L1 head box holds 3: the trace lights slot 3, then next[3]=6, then next[6]=2, then NIL. The chain jumps over slots 4 and 5 because those belong to other structures.',
    st: { allocFree: 'initial', targetList: 'L1' }, trace: 'L1'
  },
  {
    title: 'Trace L2 and read prev',
    narration: 'L2 (head 9) runs 9 → 7 → 1 → 5 → NIL. Now hover any prev cell: prev[1]=7 points exactly where next[7]=1 came from, confirming the list is doubly linked.',
    st: { allocFree: 'initial', targetList: 'L1' }, trace: 'L2'
  },
  {
    title: 'The free list needs only one link',
    narration: 'The free head (10) gives 10 → 4 → 8 → NIL. The key and prev rows of these slots are struck out with thick dotted rules — a free slot carries no data and needs no back pointer.',
    st: { allocFree: 'initial', targetList: 'L1' }, trace: 'free'
  },
  {
    title: 'Allocate a slot',
    narration: 'Allocate: slot 10 is popped off the free chain, free is reset to 4, and slot 10 is spliced onto the front of L1 — only next[10], key[10], prev[10], prev[3] and the two head pointers change (dashed outlines).',
    st: { allocFree: 'allocated', targetList: 'L1' }, trace: 'L1'
  },
  {
    title: 'Free it again',
    narration: 'Free: slot 10 is unlinked from L1, its key and prev are struck out again, next[10] is set to the old free head 4, and free points back at 10. No record ever moved in memory.',
    st: { allocFree: 'returned', targetList: 'L1' }, trace: 'free'
  }
];
var curStep = 0;
function applyStep() {
  var s = steps[curStep];
  applyState(s.st.allocFree, s.st.targetList);
  var t = document.getElementById('stepTitle');
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  if (t) t.textContent = (curStep + 1) + '. ' + s.title;
  if (n) n.textContent = s.narration;
  if (l) l.textContent = (curStep + 1) + ' / ' + steps.length;
  if (s.trace) setTimeout(function () { traceList(s.trace); }, 220);
}
function nextStep() { curStep = (curStep + 1) % steps.length; applyStep(); }
function prevStep() { curStep = (curStep - 1 + steps.length) % steps.length; applyStep(); }

/* ---------- init ---------- */
model = buildModel();
renderCells();
renderHeads();
applyStep();
window.__markRendered();
